//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry configuration.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Returns whether the configuration can make at least one attempt.
    pub const fn is_valid(&self) -> bool {
        self.max_attempts >= 1
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn validity_requires_at_least_one_attempt() {
        assert!(!RetryConfig::new(0, 10, 100).is_valid());
        assert!(RetryConfig::new(1, 10, 100).is_valid());
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub const fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    if !config.is_valid() {
        return Err(RetryError::Permanent(
            "max_attempts must be at least 1".to_owned(),
        ));
    }

    let mut attempt = 0;
    let mut delay = config.base_delay_ms;
    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= config.max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(delay.min(config.max_delay_ms));
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = RetryConfig::new(5, 10, 25);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 5 { Err(RetryError::Transient("temporary".into())) } else { Ok(()) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let error = run_job(&RetryConfig::new(4, 1, 10), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(error, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&RetryConfig::new(3, 5, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert!(matches!(result, Err(RetryError::Transient(_))));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![5, 10]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_retries_and_records_delay() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&RetryConfig::new(3, 7, 100), &mut sleeper, || {
        calls += 1;
        if calls == 1 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![7]);
}

#[test]
fn exhausted_transient_retries_return_the_last_error() {
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&RetryConfig::new(2, 10, 10), &mut sleeper, || {
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    assert_eq!(sleeper.sleeps, vec![10]);
}

